get_search_result_page.code:
import {searchResultPage} from 'webcommander-sdk';

const response = await searchResultPage.getSearchResultPage(client);
const information = response.map.search_result_page.product_information;
console.log(information.display_short_description, information.number_of_searches_per_result.items_per_page);

